// ---- společné pomocné funkce (stejné ve všech workflowech) ----
const env = (k, d = '') => { const v = $env[k]; return (v === undefined || v === null || v === '') ? d : String(v); };
const clean = (items) => (items || []).map(i => (i && i.json !== undefined) ? i.json : i)
  .filter(j => j && typeof j === 'object' && Object.values(j).some(v => v !== '' && v !== null && v !== undefined));
const blockedCountries = () => { const s = new Set(env('BLOCKED_COUNTRIES', 'CR').split(',').map(x => x.trim().toUpperCase()).filter(Boolean)); s.add('CR'); return s; };
const domainOf = (e) => { const m = String(e || '').toLowerCase().match(/@([a-z0-9.-]+)/); return m ? m[1] : ''; };
const domainOfUrl = (u) => { try { if (!u) return ''; const h = new URL(/^https?:\/\//i.test(u) ? u : 'http://' + u).hostname.toLowerCase(); return h.replace(/^www\./, ''); } catch (e) { return ''; } };
const FREE_MAIL = new Set(['gmail.com','googlemail.com','seznam.cz','email.cz','centrum.cz','volny.cz','atlas.cz','post.cz','tiscali.cz','yahoo.com','yahoo.co.uk','yahoo.ca','yahoo.com.au','hotmail.com','hotmail.co.uk','outlook.com','live.com','icloud.com','me.com','aol.com','protonmail.com','proton.me','mail.com','gmx.com','gmx.de','web.de','bigpond.com','shaw.ca','telus.net','rogers.com','comcast.net','att.net','verizon.net','btinternet.com','sky.com','virginmedia.com']);
const parseISO = (s) => { if (!s) return null; const d = DateTime.fromISO(String(s)); return d.isValid ? d : null; };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const truthy = (v) => ['true', '1', 'yes', 'ano'].includes(String(v ?? '').trim().toLowerCase());

const blocked = blockedCountries();
// UNIQUE_CITY_V2: čekající na volnou šablonu se zkouší znovu po 6 h, max 4 za běh, přednostně
const WAIT_TAG = 'šablona-obsazená:';
const waitDue = (r) => { const m = String(r.next_action || '').match(/šablona-obsazená:(\S+)/); const t = m ? parseISO(m[1]) : null; return !t || DateTime.now().diff(t, 'hours').hours >= 6; };
const waitingU = clean($input.all()).filter(r => r.id && String(r.status) === 'waiting_template' && waitDue(r))
  .sort((a, b) => String(a.created_at || '').localeCompare(String(b.created_at || ''))).slice(0, 4);
const rows = waitingU.concat(clean($input.all()).filter(r => r.id && ['new', 'changes_requested'].includes(String(r.status)))); // OWNER_NOTE_PATCH_V1
rows.sort((a, b) => ((String(b.status) === 'waiting_template') - (String(a.status) === 'waiting_template')) || String(a.created_at || '').localeCompare(String(b.created_at || '')));
const out = [];
for (const r of rows) {
  if (blocked.has(String(r.country || '').toUpperCase())) { out.push({ json: { ...r, _blocked: true } }); continue; }
  if (out.filter(o => !o.json._blocked).length < 8) out.push({ json: r });
}

// UNIQUE_CITY_V2 – pro pipeline: které leady ve stejném městě drží šablonu
const RELEASE_U = new Set(['', 'new', 'processing', 'rejected', 'changes_requested', 'skipped', 'error', 'blocked', 'needs_email',
  'waiting_template', 'lost', 'unsubscribed', 'do_not_contact', 'bounced']);
const NOREPLY_DAYS_U = Number($env.TEMPLATE_RELEASE_DAYS || 14) || 14;
const holdsU = (x) => {
  const st = String(x.status || '');
  if (RELEASE_U.has(st)) return false;
  if (st === 'sent_3' && !x.last_reply_at) { const t = parseISO(x.sent_3_at); if (t && DateTime.now().diff(t, 'days').days >= NOREPLY_DAYS_U) return false; }
  return true;
};
const allU = clean($input.all());
const ckU = (c) => String(c || '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const pickedU = out.filter(o => !o.json._blocked).map(o => o.json);
for (const o of out) {
  if (o.json._blocked) continue;
  const c = ckU(o.json.city);
  if (!c) continue;
  const ids = allU.filter(x => x.id && x.id !== o.json.id && ckU(x.city) === c && holdsU(x))
    .concat(pickedU.filter(p => p.id !== o.json.id && ckU(p.city) === c));
  o.json._active_ids = [...new Set(ids.map(x => String(x.id)))];
}
return out;

// ---- společné pomocné funkce (stejné ve všech workflowech) ----
const env = (k, d = '') => { const v = $env[k]; return (v === undefined || v === null || v === '') ? d : String(v); };
const clean = (items) => (items || []).map(i => (i && i.json !== undefined) ? i.json : i)
  .filter(j => j && typeof j === 'object' && Object.values(j).some(v => v !== '' && v !== null && v !== undefined));
const blockedCountries = () => { const s = new Set(env('BLOCKED_COUNTRIES', 'CR').split(',').map(x => x.trim().toUpperCase()).filter(Boolean)); s.add('CR'); return s; };
const domainOf = (e) => { const m = String(e || '').toLowerCase().match(/@([a-z0-9.-]+)/); return m ? m[1] : ''; };
const domainOfUrl = (u) => { try { if (!u) return ''; const h = new URL(/^https?:\/\//i.test(u) ? u : 'http://' + u).hostname.toLowerCase(); return h.replace(/^www\./, ''); } catch (e) { return ''; } };
const FREE_MAIL = new Set(['gmail.com','googlemail.com','seznam.cz','email.cz','centrum.cz','volny.cz','atlas.cz','post.cz','tiscali.cz','yahoo.com','yahoo.co.uk','yahoo.ca','yahoo.com.au','hotmail.com','hotmail.co.uk','outlook.com','live.com','icloud.com','me.com','aol.com','protonmail.com','proton.me','mail.com','gmx.com','gmx.de','web.de','bigpond.com','shaw.ca','telus.net','rogers.com','comcast.net','att.net','verizon.net','btinternet.com','sky.com','virginmedia.com']);
const parseISO = (s) => { if (!s) return null; const d = DateTime.fromISO(String(s)); return d.isValid ? d : null; };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const truthy = (v) => ['true', '1', 'yes', 'ano'].includes(String(v ?? '').trim().toLowerCase());

const lead = $('Smyčka po jednom').item.json;
const r = $input.item.json || {};
const today = DateTime.now().toFormat('d.L.');
const out = { id: lead.id };
const addNote = (s) => { out.notes = [lead.notes, s].filter(Boolean).join(' | ').slice(-1000); };
if (r.error || (!r.branch && !r.preview_url)) {
  out.status = 'error';
  addNote(`${today} /process chyba: ${String((r.error && (r.error.message || r.error.description)) || r.error || JSON.stringify(r)).slice(0, 200)}`);
  return { json: out };
}
const emails = Array.isArray(r.emails) ? r.emails : [];
const email = String(r.best_email || emails[0] || lead.email || '').trim().toLowerCase();
const phones = Array.isArray(r.phones) ? r.phones : [];
const reasonsCs = Array.isArray(r.reasons_cs) ? r.reasons_cs : [];
const reasonsEn = Array.isArray(r.reasons_en) ? r.reasons_en : [];
out.branch = r.branch || 'skip';
out.score = (r.score ?? '') === '' ? '' : Number(r.score);
out.reasons = (lead.lang === 'cs' ? reasonsCs : (reasonsEn.length ? reasonsEn : reasonsCs)).join(' | ');
out.reasons_cs = reasonsCs.join(' | ');
out.preview_url = r.preview_url || '';
out.compare_png_url = r.compare_png_url || '';
out.og_png_url = r.og_png_url || '';
out.extracted_offer = String(r.offer_summary || '').slice(0, 900); // OWNER_NOTE_PATCH_V1
out.offer_photos = String(r.offer_photos || '').slice(0, 1500);
const rebuild = String(lead.status) === 'changes_requested';
out.industry = r.industry || '';
out.legal_regime = r.legal_regime || lead.legal_regime || 'unknown';
if (r.tz) out.tz = r.tz;
if (email && email.includes('@')) out.email = email;
if (!lead.phone && (phones[0] || r.phone)) out.phone = phones[0] || r.phone;
const notes = [];
const waitU = out.branch === 'skip' && Array.isArray(r.warnings) && r.warnings.some(w => String(w).startsWith('SABLONA_OBSAZENA')); // UNIQUE_CITY_V2
if (waitU) { r.warnings = String(lead.status) === 'waiting_template' ? [] : r.warnings.map(w => String(w).replace(/^SABLONA_OBSAZENA:\s*/, '')); }
if (Array.isArray(r.warnings) && r.warnings.length) notes.push('upozornění: ' + r.warnings.join('; '));
if (out.legal_regime === 'blocked' || out.branch === 'blocked') { out.status = 'blocked'; notes.push(r.legal_note_cs || 'blokovaný právní režim'); }
else if (waitU) { out.status = 'waiting_template'; out.next_action = 'šablona-obsazená:' + DateTime.now().toISO(); }
else if (out.branch === 'skip') { out.status = 'skipped'; }
else if (out.email) { out.status = 'awaiting_approval'; out.next_action = ''; if (rebuild) { out.batch_id = ''; out.notified_at = ''; out.approved_at = ''; notes.push('přestavěno podle poznámky majitele'); } }
else if (out.branch === 'no_website') { out.status = 'skipped'; notes.push('bez webu a bez veřejného e-mailu – neoslovujeme'); }
else { out.status = 'needs_email'; out.next_action = 'doplnit e-mail'; }
if (out.legal_regime === 'unknown' && out.status === 'awaiting_approval') notes.push('právní režim země neznámý – ověř před schválením');
if (out.legal_regime === 'corporate_only' && out.status === 'awaiting_approval') notes.push('UK/IE: ověř, že jde o Ltd/PLC (PECR), ne sole trader');
if (notes.length) addNote(`${today} ${notes.join('; ')}`);
return { json: out };
